                if isinstance(msg, dict):
                    content = msg.get('content', '')
                    if isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'text':
                                text += c.get('text', '')
                    elif isinstance(content, str):
                        text = content
                user_messages.append((data.get('timestamp') or data.get('id'), text[:80].replace('\n', ' ')))

print('Message roles:', roles)
print(f'User message count: {len(user_messages)}')
for idx, (ts, preview) in enumerate(user_messages):
    print(f'{idx+1}: [{ts}] {preview}')
"

