                };
                activeStream = await navigator.mediaDevices.getUserMedia(constraints);
                video.srcObject = activeStream;
            } catch (err) {
                console.warn("Hardware camera access failed:", err);
                statusBadge.textContent = "Không thể mở camera tự động. Vui lòng bấm liên kết bên dưới.";
                statusBadge.className = "status-badge error";
            }
        }

        window.addEventListener('DOMContentLoaded', initCamera);

        fallbackBtn.addEventListener('click', () => fallbackFileInput.click());
        fallbackFileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files[0]) {
                processAndUploadBlob(e.target.files[0]);
            }
        });

        shutterBtn.addEventListener('click', async () => {
            const phone = driverPhoneInput.value.trim();
            if (!phone) {
                statusBadge.textContent = "Vui lòng nhập số điện thoại hoặc mã tài xế!";
                statusBadge.className = "status-badge error";
                driverPhoneInput.focus();
                return;
            }

            if (!video.videoWidth) {
                statusBadge.textContent = "Camera chưa sẵn sàng, vui lòng đợi giây lát...";
                statusBadge.className = "status-badge error";
                return;
            }

            // Haptic vibration feedback on mobile
            if (navigator.vibrate) navigator.vibrate(50);

            // Shutter snapshot
            statusBadge.textContent = "Đang nén ảnh WebP trên điện thoại...";
            statusBadge.className = "status-badge loading";
            shutterBtn.disabled = true;

            const scale = Math.min(1.0, 1280 / Math.max(video.videoWidth, video.videoHeight));
            canvas.width = Math.round(video.videoWidth * scale);
            canvas.height = Math.round(video.videoHeight * scale);
            const ctx = canvas.getContext('2d');
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

            // Client-side WebP compression (quality 0.82)
            canvas.toBlob(async (blob) => {
                if (!blob) {
                    statusBadge.textContent = "Lỗi xuất khung hình canvas!";
                    statusBadge.className = "status-badge error";
                    shutterBtn.disabled = false;
                    return;
                }
                await processAndUploadBlob(blob);
            }, 'image/webp', 0.82);
        });

        async function processAndUploadBlob(blob) {
            statusBadge.textContent = `Đang gửi ảnh (${Math.round(blob.size / 1024)}KB) & chạy AI thẩm định...`;
            statusBadge.className = "status-badge loading";

            const formData = new FormData();
            formData.append('survey_photo', blob, 'survey_capture.webp');
            formData.append('driver_phone', driverPhoneInput.value.trim());
            formData.append('license_plate', licensePlateInput.value.trim().toUpperCase());

            try {
                const resp = await fetch('/api/v1/survey/submit-webrtc', {
                    method: 'POST',
                    body: formData
                });
                const result = await resp.json();

                if (resp.ok && result.status === 'APPROVED') {
                    statusBadge.textContent = `✅ HỢP LỆ! Mã phiếu #${result.submission_id}`;
                    statusBadge.className = "status-badge success";
                } else if (result.status === 'REJECTED') {
                    statusBadge.textContent = `❌ TỪ CHỐI: ${result.reason || 'Ảnh không hợp lệ, vui lòng chụp lại'}`;
                    statusBadge.className = "status-badge error";
                } else {
                    statusBadge.textContent = `ℹ️ Đã nhận phiếu #${result.submission_id || ''} (${result.status || 'Chờ duyệt'})`;
                    statusBadge.className = "status-badge success";
                }
            } catch (err) {
                console.error("Upload failed:", err);
                statusBadge.textContent = "Lỗi kết nối máy chủ, vui lòng thử lại!";
                statusBadge.className = "status-badge error";
            } finally {
                shutterBtn.disabled = false;
            }
        }
    </script>
</body>
</html>
