                        """,
                        (
                            submission_id,
                            driver_phone,
                            driver_name or "Tài xế",
                            f"SN-{license_plate or 'AUTO'}",
                            "APPROVED" if compliance.is_compliant else "REJECTED",
                            compliance.feedback_message_vi if not compliance.is_compliant else None,
